<?php
namespace App\Policies; use App\Models\Invoice; use App\Models\User;
class InvoicePolicy { private function can(User $u,string $p):bool{return method_exists($u,'hasPermission')?$u->hasPermission($p):($u->isSuperAdmin??false);} public function viewAny(User $u):bool{return $this->can($u,'invoices.view');} public function view(User $u,Invoice $i):bool{return $this->can($u,'invoices.view');} public function create(User $u):bool{return $this->can($u,'invoices.create');} public function update(User $u,Invoice $i):bool{return $this->can($u,'invoices.edit');} public function delete(User $u,Invoice $i):bool{return $this->can($u,'invoices.delete');} public function issue(User $u,Invoice $i):bool{return $this->can($u,'invoices.issue');} public function send(User $u,Invoice $i):bool{return $this->can($u,'invoices.send');} public function cancel(User $u,Invoice $i):bool{return $this->can($u,'invoices.cancel');} public function duplicate(User $u,Invoice $i):bool{return $this->can($u,'invoices.duplicate');} public function export(User $u):bool{return $this->can($u,'invoices.export');} public function print(User $u,Invoice $i):bool{return $this->can($u,'invoices.print');} public function pdf(User $u,Invoice $i):bool{return $this->can($u,'invoices.pdf');} }
